def list_nonconformities():
    return deepcopy(NONCONFORMITIES)


def create_nonconformity(payload):
    global NEXT_ID
    required = ["description", "lot_code", "responsible", "shift", "equipment", "line"]
    missing = [field for field in required if not str(payload.get(field, "")).strip()]
    if missing:
        raise ValueError("Campos obrigatorios: " + ", ".join(missing))
    item = {
        "id": f"NC-{NEXT_ID}",
        "created_at": datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        "description": payload["description"].strip(),
        "lot_code": payload["lot_code"].strip().upper(),
        "responsible": payload["responsible"].strip(),
        "shift": payload["shift"].strip().upper(),
        "equipment": payload["equipment"].strip().upper(),
        "line": payload["line"].strip() if payload["line"].lower().startswith("linha") else f"Linha {payload['line'].strip()}",
    }
    NEXT_ID += 1
    NONCONFORMITIES.insert(0, item)
    return deepcopy(item)


def analyze_root_cause(record_id):
    record = next((item for item in NONCONFORMITIES if item["id"] == record_id), None)
    if not record:
        raise KeyError("Registro nao encontrado.")
    related = [
        item for item in NONCONFORMITIES
        if item["id"] != record_id and (item["equipment"] == record["equipment"] or item["line"] == record["line"])
    ]
    cause = f"Setup ou desgaste de molde no {record['equipment']}"
    return {
        "record": deepcopy(record),
        "suggested_causes": [
            {"cause": cause, "evidence": f"{len(related)} registro(s) similar(es) no historico."},
            {"cause": "Variacao de materia-prima afetando contracao da peca", "evidence": "Lotes correlatos usam a mesma familia de material."},
        ],
        "five_whys": [
            "Defeito dimensional detectado na inspecao.",
            cause,
            "Parametros de processo podem ter variado sem contencao imediata.",
            "Historico mostra recorrencia no mesmo equipamento/linha.",
            "Revisar setup, bloquear lote e acompanhar eficacia por 7 dias.",
        ],
        "action_plan": [
            {"action": f"Bloquear {record['lot_code']} ate triagem.", "owner": "Qualidade", "due": "Hoje", "status": "Aberta"},
            {"action": f"Revalidar setup do {record['equipment']}.", "owner": "Processos", "due": "24h", "status": "Aberta"},
            {"action": "Medir lotes correlatos.", "owner": "Laboratorio", "due": "48h", "status": "Aberta"},
        ],
    }


def trace_lot(lot_code):
    key = str(lot_code).strip().upper()
    if key not in LOTS:
        raise KeyError(f"Lote nao encontrado: {key}")
    return deepcopy(LOTS[key])


def default_briefing():
    try:
        return DEFAULT_BRIEF_PATH.read_text(encoding="utf-8")
    except OSError:
        return "Empresa: Rivexx Componentes. Aplicacao web interna para qualidade e rastreabilidade."


