class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        try:
            path = urlparse(self.path).path
            if path == "/api/health":
                self.json({"status": "ok"})
            elif path == "/api/briefing":
                self.json({"briefing": default_briefing()})
            elif path == "/api/squad/latest":
                self.json(LAST_SQUAD_RUN or run_squad_observability(default_briefing()))
            elif path == "/api/nonconformities":
                self.json({"items": list_nonconformities()})
            elif path.startswith("/api/root-cause/"):
                self.json(analyze_root_cause(unquote(path.rsplit("/", 1)[-1])))
            elif path.startswith("/api/traceability/"):
                self.json(trace_lot(unquote(path.rsplit("/", 1)[-1])))
            else:
                self.static(path)
        except ValueError as exc:
            self.json({"error": str(exc)}, HTTPStatus.BAD_REQUEST)
        except KeyError as exc:
            self.json({"error": str(exc).strip("'")}, HTTPStatus.NOT_FOUND)

    def do_POST(self):
        try:
            path = urlparse(self.path).path
            length = int(self.headers.get("Content-Length", "0"))
            payload = json.loads(self.rfile.read(length).decode("utf-8")) if length else {}
            if path == "/api/squad/run":
                self.json(run_squad_observability(payload.get("briefing", "")))
                return
            if path != "/api/nonconformities":
                self.json({"error": "Rota nao encontrada."}, HTTPStatus.NOT_FOUND)
                return
            self.json(create_nonconformity(payload), HTTPStatus.CREATED)
        except ValueError as exc:
            self.json({"error": str(exc)}, HTTPStatus.BAD_REQUEST)

    def static(self, path):
        target = FRONTEND / ("index.html" if path in ("", "/") else path.lstrip("/"))
        if not target.exists():
            self.json({"error": "Arquivo nao encontrado."}, HTTPStatus.NOT_FOUND)
            return
        content_type = "text/css" if target.suffix == ".css" else "application/javascript" if target.suffix == ".js" else "text/html"
        body = target.read_bytes()
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def json(self, data, status=HTTPStatus.OK):
        body = json.dumps(data, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8000)
    args = parser.parse_args()
    server = ThreadingHTTPServer(("127.0.0.1", args.port), Handler)
    print(f"Rivexx rodando em http://127.0.0.1:{args.port}")
    server.serve_forever()


if __name__ == "__main__":
    main()
